//! The golden fixtures, decoded with the app's models.
//!
//! Replies come from the canonical `protocol/fixtures/replies/` (one
//! `RemoteReply` per method, generated by the Swift implementation). Control
//! exchanges come from `protocol/fixtures/control/` once the daemon adds it,
//! and from this crate's samples in `tests/fixtures/control/` until then.

mod common;

use common::{fixture_dir, json_files, stem};
use planmeter::chart::ChartData;
use planmeter::client::{Client, ClientError};
use planmeter::http::{self, decode_segment};
use planmeter::models::*;
use planmeter::range::TimeRange;
use serde::Deserialize;
use serde_json::Value;
use std::os::unix::net::UnixListener;

fn read(path: &std::path::Path) -> Vec<u8> {
    std::fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// `replies/<name>.json`, which must hold exactly one payload field.
fn reply(name: &str) -> RemoteReply {
    let path = fixture_dir("replies").join(format!("{name}.json"));
    let reply: RemoteReply =
        serde_json::from_slice(&read(&path)).unwrap_or_else(|e| panic!("{name}: {e}"));
    let set = [
        reply.summary.is_some(),
        reply.models.is_some(),
        reply.timeline.is_some(),
        reply.limits.is_some(),
        reply.accounts.is_some(),
        reply.error.is_some(),
    ];
    assert_eq!(
        set.iter().filter(|s| **s).count(),
        1,
        "{name}: exactly one payload field"
    );
    reply
}

#[test]
fn every_reply_fixture_decodes() {
    let files = json_files("replies");
    assert!(!files.is_empty(), "no reply fixtures");
    for path in files {
        reply(&stem(&path));
    }
}

#[test]
fn summary_reply() {
    let s = reply("summary").summary.unwrap();
    assert!(s.to > s.from);
    assert!(!s.groups.is_empty());
    let groups: f64 = s.groups.iter().map(|g| g.totals.cost_usd).sum();
    assert!(
        (groups - s.total.cost_usd).abs() < 0.01,
        "group costs add up to the total"
    );
    for g in &s.groups {
        let accounts: f64 = g.accounts.iter().map(|a| a.totals.cost_usd).sum();
        assert!(
            (accounts - g.totals.cost_usd).abs() < 0.01,
            "{}: accounts add up",
            g.group
        );
        for a in &g.accounts {
            assert_eq!(
                a.account.group, g.group,
                "{} sits in its group",
                a.account.id
            );
        }
    }
    assert!(s.total.cached_share() >= 0.0 && s.total.cached_share() <= 1.0);
    assert!(!s.server_name.is_empty() && !s.pricing_source.is_empty());
}

#[test]
fn timeline_reply_covers_a_sub_day_window_with_baselines() {
    let t = reply("timeline").timeline.unwrap();
    assert_eq!(t.minutes, Some(60), "a 60-minute window");
    let step = RemoteTimeline::step_seconds(&t.resolution).expect("fixed-step resolution");
    assert_eq!(
        t.periods.len() as i64 * step,
        60 * 60,
        "periods cover the hour"
    );
    for p in &t.points {
        assert!(
            t.accounts.iter().any(|a| a.id == p.account_id),
            "point account {} is listed",
            p.account_id
        );
        assert!(
            t.periods.contains(&p.period),
            "point period is a listed period"
        );
        if let Some(b) = p.baseline_cost_usd {
            assert!(b <= p.cost_usd + 1e-9, "baseline is part of the cost");
        }
    }
    assert!(
        t.points.iter().any(|p| p.baseline_cost_usd.is_some()),
        "has untimed baselines"
    );

    // What the chart draws from it.
    let chart = ChartData::build(&t);
    assert_eq!(
        chart.bars.len(),
        t.periods.len(),
        "zero-filled, one bar per period"
    );
    assert!(chart.has_baseline);
    let points: f64 = t.points.iter().map(|p| p.cost_usd).sum();
    assert!((chart.total - points).abs() < 1e-9);
    for bar in &chart.bars {
        let first_timed = bar
            .segments
            .iter()
            .position(|s| !s.baseline)
            .unwrap_or(bar.segments.len());
        assert!(
            bar.segments[first_timed..].iter().all(|s| !s.baseline),
            "baselines stack first"
        );
    }
    // A coarser view of the same data keeps every dollar.
    if let Some(wide) = t.rebucketed("15m") {
        let wide_total: f64 = wide.points.iter().map(|p| p.cost_usd).sum();
        assert!((wide_total - points).abs() < 1e-9);
    }
}

#[test]
fn models_reply() {
    let models = reply("models").models.unwrap();
    assert!(!models.is_empty());
    for m in &models {
        assert!(!m.model.is_empty() && !m.account_id.is_empty());
        if !m.priced {
            assert_eq!(
                m.totals.cost_usd, 0.0,
                "{}: unpriced models cost nothing",
                m.model
            );
        }
    }
    let costs: Vec<f64> = models.iter().map(|m| m.totals.cost_usd).collect();
    assert!(costs.windows(2).all(|w| w[0] >= w[1]), "sorted by cost");
}

#[test]
fn limits_reply() {
    let limits = reply("limits").limits.unwrap();
    assert!(!limits.note.is_empty());
    for entry in &limits.accounts {
        for w in &entry.windows {
            assert!(w.used_percent >= 0.0, "{}: used percent", w.label);
            assert!(w.window_minutes > 0);
            assert!(!w.label.is_empty());
        }
        assert!(
            !entry.windows.is_empty() || entry.note.is_some(),
            "{}: windows or a note",
            entry.account.id
        );
    }
}

#[test]
fn accounts_reply() {
    let a = reply("accounts").accounts.unwrap();
    assert!(!a.accounts.is_empty());
    for s in &a.sources {
        assert!(
            ["ok", "missing", "partial", "failed"].contains(&s.status.as_str()),
            "{}: status {}",
            s.path,
            s.status
        );
    }
    for account in &a.accounts {
        if let Some(hex) = &account.accent_color_hex {
            assert!(
                planmeter::format::parse_hex(hex).is_some(),
                "{}: accent {hex}",
                account.id
            );
        }
    }
}

#[test]
fn error_reply() {
    assert!(!reply("error").error.unwrap().is_empty());
}

/// A control fixture: one request and the daemon's answer.
#[derive(Debug, Deserialize)]
struct Exchange {
    request: FixtureRequest,
    response: FixtureResponse,
}

#[derive(Debug, Deserialize)]
struct FixtureRequest {
    method: String,
    path: String,
    #[serde(default)]
    body: Option<Value>,
}

#[derive(Debug, Deserialize)]
struct FixtureResponse {
    status: u16,
    #[serde(default)]
    body: Value,
}

fn exchanges() -> Vec<(String, Exchange)> {
    let files = json_files("control");
    assert!(!files.is_empty(), "no control fixtures");
    files
        .iter()
        .map(|path| {
            let name = stem(path);
            let exchange =
                serde_json::from_slice(&read(path)).unwrap_or_else(|e| panic!("{name}: {e}"));
            (name, exchange)
        })
        .collect()
}

fn segments(path: &str) -> Vec<String> {
    path.split('?')
        .next()
        .unwrap_or(path)
        .trim_matches('/')
        .split('/')
        .map(decode_segment)
        .collect()
}

#[test]
fn every_control_fixture_decodes() {
    let mut kinds = Vec::new();
    for (name, ex) in exchanges() {
        let body = ex.response.body.clone();
        if !(200..300).contains(&ex.response.status) {
            let e: ErrorBody =
                serde_json::from_value(body).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert!(!e.error.is_empty(), "{name}: error message");
            kinds.push("error");
            continue;
        }
        let segs = segments(&ex.request.path);
        let segs: Vec<&str> = segs.iter().map(String::as_str).collect();
        let kind = match segs.as_slice() {
            ["v1", "status"] | ["v1", "refresh"] => {
                let s: DaemonStatus =
                    serde_json::from_value(body).unwrap_or_else(|e| panic!("{name}: {e}"));
                assert!(s.api_version >= 1, "{name}");
                "status"
            }
            ["v1", "settings", ..] => {
                let s: HostSettings =
                    serde_json::from_value(body).unwrap_or_else(|e| panic!("{name}: {e}"));
                for (range, t) in &s.spend_thresholds {
                    assert!(
                        TimeRange::from_id(range).is_some(),
                        "{name}: range id {range}"
                    );
                    assert!(t.is_valid(), "{name}: threshold for {range}");
                }
                "settings"
            }
            ["v1", "remote", ..] => {
                let r: RemoteStatus =
                    serde_json::from_value(body).unwrap_or_else(|e| panic!("{name}: {e}"));
                if let Some(invite) = &r.invite {
                    assert!(
                        invite.url.starts_with("planmeter://pair?"),
                        "{name}: invite url"
                    );
                }
                "remote"
            }
            ["v1", "rpc"] => {
                let reply: RemoteReply =
                    serde_json::from_value(body).unwrap_or_else(|e| panic!("{name}: {e}"));
                assert!(
                    reply.error.is_some() || reply != RemoteReply::default(),
                    "{name}: empty reply"
                );
                "rpc"
            }
            // A newer endpoint this client does not use yet.
            _ => "other",
        };
        kinds.push(kind);
    }
    for required in ["status", "settings", "remote", "rpc", "error"] {
        assert!(
            kinds.contains(&required),
            "missing a {required} control fixture"
        );
    }
}

/// Numbers compare by value: `25` and `25.0` are the same JSON number to Swift.
fn normalize(v: Value) -> Value {
    match v {
        Value::Number(n) => serde_json::json!(n.as_f64()),
        Value::Array(a) => Value::Array(a.into_iter().map(normalize).collect()),
        Value::Object(o) => Value::Object(o.into_iter().map(|(k, v)| (k, normalize(v))).collect()),
        other => other,
    }
}

fn from<T: serde::de::DeserializeOwned>(v: Value) -> T {
    serde_json::from_value(v).expect("fixture request body")
}

/// Issues the client call that produces this fixture's request.
fn call(client: &Client, req: &FixtureRequest) -> Result<(), ClientError> {
    let body = req.body.clone().unwrap_or(Value::Null);
    let segs = segments(&req.path);
    let segs: Vec<&str> = segs.iter().map(String::as_str).collect();
    match (req.method.as_str(), segs.as_slice()) {
        ("GET", ["v1", "status"]) => client.status().map(drop),
        ("POST", ["v1", "refresh"]) => client
            .refresh(body["forceAccountUsage"].as_bool().unwrap_or(false))
            .map(drop),
        ("POST", ["v1", "rpc"]) => client.rpc(&from(body)).map(drop),
        ("GET", ["v1", "settings"]) => client.settings().map(drop),
        ("PUT", ["v1", "settings", "groups", id]) => {
            let b: GroupOverrideBody = from(body);
            client.set_group(id, b.group).map(drop)
        }
        ("PUT", ["v1", "settings", "spend"]) => {
            let b: SpendSettingsBody = from(body);
            client.set_spend(b.groups, b.thresholds).map(drop)
        }
        ("GET", ["v1", "remote"]) => client.remote().map(drop),
        ("PUT", ["v1", "remote"]) => client.set_remote(&from(body)).map(drop),
        ("POST", ["v1", "remote", "invite"]) => client.create_invite().map(drop),
        ("DELETE", ["v1", "remote", "invite"]) => client.cancel_invite().map(drop),
        ("DELETE", ["v1", "remote", "devices", id]) => client.revoke_device(id).map(drop),
        _ => {
            let response = client.send(&req.method, &req.path, None)?;
            if response.is_success() {
                Ok(())
            } else {
                Err(ClientError::Http {
                    status: response.status,
                    message: String::new(),
                })
            }
        }
    }
}

/// Replays every control fixture against the real client over a socket: the
/// client must send exactly the fixture's request and accept its response.
#[test]
fn client_requests_match_control_fixtures() {
    let dir = tempfile::tempdir().unwrap();
    for (name, ex) in exchanges() {
        let socket = dir.path().join(format!("{name}.sock"));
        let listener = UnixListener::bind(&socket).unwrap();
        let status = ex.response.status;
        let response_body = serde_json::to_vec(&ex.response.body).unwrap();
        let server = std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let request = http::read_request(&stream).unwrap();
            http::write_response(&mut stream, status, &response_body).unwrap();
            request
        });
        let result = call(&Client::new(&socket), &ex.request);
        let sent = server.join().unwrap();

        assert_eq!(sent.method, ex.request.method, "{name}: method");
        assert_eq!(sent.path, ex.request.path, "{name}: path");
        let sent_body: Value = if sent.body.is_empty() {
            Value::Null
        } else {
            serde_json::from_slice(&sent.body)
                .unwrap_or_else(|e| panic!("{name}: client sent invalid JSON: {e}"))
        };
        let expected = ex.request.body.clone().unwrap_or(Value::Null);
        assert_eq!(
            normalize(sent_body),
            normalize(expected),
            "{name}: request body"
        );
        match (&result, (200..300).contains(&status)) {
            (Ok(()), true) => {}
            (Err(ClientError::Http { status: s, .. }), false) => assert_eq!(*s, status, "{name}"),
            other => panic!("{name}: unexpected client result {other:?}"),
        }
    }
}

#[test]
fn swift_style_json_decodes() {
    // Swift's JSONEncoder omits nil optionals, sorts keys, escapes `/` as
    // `\/`, and writes whole doubles as integers; extra fields from newer
    // hosts must be ignored, and null reads as absent.
    let json = br#"{"summary":null,"timeline":{"accounts":[{"group":"work","id":"claude:home:\/home\/dev\/.claude","name":"A","provider":"claude","providerName":"Claude Code"}],"days":1,"futureField":true,"periods":["2026-10-19T12:00:00Z"],"points":[{"accountId":"claude:home:\/home\/dev\/.claude","costUsd":128,"period":"2026-10-19T12:00:00Z","tokens":42}],"resolution":"hour"}}"#;
    let reply: RemoteReply = serde_json::from_slice(json).unwrap();
    let t = reply.timeline.unwrap();
    assert_eq!(t.accounts[0].id, "claude:home:/home/dev/.claude");
    assert_eq!(t.points[0].cost_usd, 128.0);
    assert_eq!(t.points[0].baseline_cost_usd, None);
    assert_eq!(t.accounts[0].accent_color_hex, None);
    assert!(reply.summary.is_none());
}
